import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.vLhlLNVn.js";const r="/assets/daten-loeschen.B-P9AWbq.png",i="/assets/probleme-ohne-befund.Dc7Axqfu.png",n="/assets/probleme-periodenwechsel.B11voC4m.png",f=JSON.parse('{"title":"Operation and maintenance","description":"","frontmatter":{"order":5,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/05.betrieb-und-wartung.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","filePath":"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","lastUpdated":null}'),d={name:"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md"};function l(h,e,u,c,p,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="operation-and-maintenance" tabindex="-1">Operation and maintenance <a class="header-anchor" href="#operation-and-maintenance" aria-label="Permalink to &quot;Operation and maintenance&quot;">​</a></h1><p><a id="update-sourceanalytix-downgrade"></a></p><h2 id="how-do-i-update-sourceanalytix-and-what-is-a-downgrade" tabindex="-1">How do I update SourceAnalytix (and what is a downgrade)? <a class="header-anchor" href="#how-do-i-update-sourceanalytix-and-what-is-a-downgrade" aria-label="Permalink to &quot;How do I update SourceAnalytix (and what is a downgrade)?&quot;">​</a></h2><p>Like any adapter, on the &quot;Adapters&quot; tab, as long as the &quot;latest&quot; repository is active in the system settings. SourceAnalytix is not in &quot;stable&quot; yet, so you won&#39;t see an update there. Values and settings are kept during the update.</p><ol><li>Make a backup.</li><li>In the system settings, choose &quot;latest&quot; under &quot;Repositories&quot;.</li><li>On the &quot;Adapters&quot; tab, click the update button for SourceAnalytix.</li><li>Afterwards, check the &quot;Problems&quot; tab of the instance settings for anything reported.</li></ol><p>From the console, use <code>iobroker upgrade sourceanalytix</code>, also only with &quot;latest&quot;. If ioBroker offers no update, check the <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">requirements</a>. After an installation from GitHub, Admin shows no updates; install once from &quot;latest&quot; over it.</p><h3 id="downgrade" tabindex="-1">Downgrade <a class="header-anchor" href="#downgrade" aria-label="Permalink to &quot;Downgrade&quot;">​</a></h3><p>A downgrade installs an older version over the existing one, for example if a new version has a bug on your system. Turn on expert mode on the &quot;Adapters&quot; tab and choose &quot;Install specific version&quot; for SourceAnalytix. In the console: <code>iobroker upgrade sourceanalytix@&lt;version&gt;</code>, without a &quot;v&quot; before the number.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>An older version doesn&#39;t know newer settings and may write values differently. When in doubt, restore the backup instead of just changing the version.</p></div><p>Versions with a suffix such as <code>-beta.0</code> are pre-releases for testing. <code>0.8.0</code> is newer than <code>0.8.0-beta.0</code>.</p><p><strong>See also:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Values are 0 after an update or restore</a> · <a href="#data-back-up-move-new">Where is the data?</a></p><p><a id="disable-datapoint-remove-sources-states"></a></p><h2 id="how-do-i-switch-off-a-datapoint-or-remove-sources-and-states" tabindex="-1">How do I switch off a datapoint or remove sources and states? <a class="header-anchor" href="#how-do-i-switch-off-a-datapoint-or-remove-sources-and-states" aria-label="Permalink to &quot;How do I switch off a datapoint or remove sources and states?&quot;">​</a></h2><p>Open the source in the instance settings and choose &quot;Deactivate&quot; or &quot;Delete data&quot; under &quot;Actions&quot;. &quot;Deactivate&quot; pauses the source and keeps everything. &quot;Delete data&quot; removes folders and settings for good.</p><table tabindex="0"><thead><tr><th></th><th>&quot;Deactivate&quot;</th><th>&quot;Delete data&quot;</th></tr></thead><tbody><tr><td>Folder <code>sourceanalytix.0.&lt;device&gt;</code> with all years</td><td>stays</td><td>is deleted</td></tr><tr><td>Source settings (price, start values, offset)</td><td>stay</td><td>are deleted</td></tr><tr><td>Undo</td><td>with &quot;Activate&quot;</td><td>not possible</td></tr></tbody></table><p>When deleting, the dialog shows what will disappear. To confirm, type the source&#39;s name and click &quot;Delete for good&quot;.</p><p><img src="'+r+'" alt="The &quot;Delete data&quot; dialog with the list of deleted content and the confirmation field"></p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>&quot;Delete data&quot; cannot be undone. If you only want to pause, use &quot;Deactivate&quot;.</p></div><h3 id="the-switch-on-the-datapoint-on-the-objects-tab" tabindex="-1">The switch on the datapoint on the &quot;Objects&quot; tab <a class="header-anchor" href="#the-switch-on-the-datapoint-on-the-objects-tab" aria-label="Permalink to &quot;The switch on the datapoint on the &quot;Objects&quot; tab&quot;">​</a></h3><p>You can switch it off for several datapoints at once, say after enabling many by mistake. This removes those sources&#39; settings, including the start values; the folders with the values stay. To pause, &quot;Deactivate&quot; is the right way.</p><h3 id="datapoint-deleted" tabindex="-1">Datapoint deleted <a class="header-anchor" href="#datapoint-deleted" aria-label="Permalink to &quot;Datapoint deleted&quot;">​</a></h3><p>If you delete the source datapoint, SourceAnalytix switches the source off and keeps the values. The &quot;Problems&quot; tab reports &quot;Datapoint no longer exists&quot;. A folder without a datapoint appears in the overview as &quot;Folder without datapoint&quot; and can be deleted there.</p><h3 id="removing-single-periods" tabindex="-1">Removing single periods <a class="header-anchor" href="#removing-single-periods" aria-label="Permalink to &quot;Removing single periods&quot;">​</a></h3><p>If you no longer want quarters, for example, turn the option off under &quot;Main settings&quot;. The page asks first, because this year&#39;s states are deleted. States you delete by hand are recreated by SourceAnalytix as long as the option is on.</p><p><strong>See also:</strong> <a href="#restart-datapoint-clean-up-old">Starting over</a> · <a href="#data-back-up-move-new">Where is the data?</a></p><p><a id="data-back-up-move-new"></a></p><h2 id="where-is-the-data-how-do-i-back-it-up-and-how-do-i-move-it" tabindex="-1">Where is the data, how do I back it up and how do I move it? <a class="header-anchor" href="#where-is-the-data-how-do-i-back-it-up-and-how-do-i-move-it" aria-label="Permalink to &quot;Where is the data, how do I back it up and how do I move it?&quot;">​</a></h2><p>In ioBroker itself; there is no separate database. A full ioBroker backup, for example with BackItUp, contains everything. To move, restore it on the new system, but not shortly before midnight.</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Values of all periods and years</td><td>folder <code>sourceanalytix.0.&lt;device&gt;</code></td></tr><tr><td>Source settings with start values and offset</td><td>object of the source datapoint, <code>common.custom.sourceanalytix.0</code></td></tr><tr><td>Price definitions and options</td><td>instance settings</td></tr><tr><td>Price history</td><td><code>sourceanalytix.0.priceHistory</code> and <code>basicPriceHistory</code></td></tr><tr><td>Recorded history</td><td>your history adapter</td></tr></tbody></table><p>A backup of only <code>sourceanalytix.0</code> is not enough, because start values and offset are stored on the source datapoint. If ioBroker runs on Redis, include the Redis backup.</p><h3 id="moving-to-new-hardware" tabindex="-1">Moving to new hardware <a class="header-anchor" href="#moving-to-new-hardware" aria-label="Permalink to &quot;Moving to new hardware&quot;">​</a></h3><ol><li>Make a full backup on the old system.</li><li>Install ioBroker and SourceAnalytix on the new system and restore the backup.</li><li>Start the instance. It catches up missed period rollovers once.</li><li>Check the &quot;Problems&quot; tab and compare the total with your meter.</li></ol><p><img src="'+i+'" alt="The &quot;Problems&quot; tab with no findings"></p><p>Recreating the sources on the new system does not replace the restore: SourceAnalytix then starts at 0. If the datapoint gets a new ID, it is a new source; the old folder stays as an archive.</p><p><strong>See also:</strong> <a href="#iobroker-was-down-midnight-recover">ioBroker was off at midnight</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Values 0 after a restore</a></p><p><a id="restart-datapoint-clean-up-old"></a></p><h2 id="how-do-i-start-over-with-a-datapoint-and-clean-up-old-years" tabindex="-1">How do I start over with a datapoint and clean up old years? <a class="header-anchor" href="#how-do-i-start-over-with-a-datapoint-and-clean-up-old-years" aria-label="Permalink to &quot;How do I start over with a datapoint and clean up old years?&quot;">​</a></h2><p>Delete the source&#39;s data with &quot;Delete data&quot; and create it again with &quot;Add source&quot;, using &quot;Count from now&quot;. All periods then start at 0. Deleting only the folder on the &quot;Objects&quot; tab is not enough, because the settings on the datapoint stay.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>This also removes the previous total. If you only want to repair wrong numbers, use <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Align meter reading</a>.</p></div><h3 id="cleaning-up-old-years" tabindex="-1">Cleaning up old years <a class="header-anchor" href="#cleaning-up-old-years" aria-label="Permalink to &quot;Cleaning up old years&quot;">​</a></h3><p>Folders of closed years such as <code>sourceanalytix.0.&lt;device&gt;.2023</code> are pure history. You may delete them on the &quot;Objects&quot; tab. Keep <code>currentYear</code>, <code>cumulativeReading</code>, <code>periodMemory</code> and the current year&#39;s folder. &quot;Recalculate costs from date&quot; skips deleted years.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values</a> · <a href="./werte-auswerten#evaluate-across-years-adjusting-everything">Evaluating across several years</a></p><p><a id="iobroker-was-down-midnight-recover"></a></p><h2 id="iobroker-was-off-at-midnight-how-do-i-catch-up-the-day-rollover" tabindex="-1">ioBroker was off at midnight: how do I catch up the day rollover? <a class="header-anchor" href="#iobroker-was-off-at-midnight-how-do-i-catch-up-the-day-rollover" aria-label="Permalink to &quot;ioBroker was off at midnight: how do I catch up the day rollover?&quot;">​</a></h2><p>Usually you don&#39;t have to. SourceAnalytix catches up missed rollovers on start and also checks every hour whether one is missing. It splits the consumption across midnight by time between the old and the new day.</p><p>If a rollover is still missing, the &quot;Problems&quot; tab reports &quot;Period rollover missed&quot; with &quot;Recover&quot;. The source&#39;s &quot;Recover periods&quot; action does the same. Both only affect that source.</p><p><img src="'+n+`" alt="The &quot;Problems&quot; tab with &quot;Period rollover missed&quot; and the &quot;Recover&quot; button"></p><p>If the outage lasted several days, SourceAnalytix processes only one rollover; the days in between get no value of their own. Values that arrive during a rollover are processed afterwards, in order.</p><h3 id="from-a-script-or-a-vis-button" tabindex="-1">From a script or a VIS button <a class="header-anchor" href="#from-a-script-or-a-vis-button" aria-label="Permalink to &quot;From a script or a VIS button&quot;">​</a></h3><p>Write <code>true</code> to <code>sourceanalytix.0.info.recoverPeriods</code>, and SourceAnalytix catches up the rollovers of all sources. From a script, it also works for a single source:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {source: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;ID of the source datapoint&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (result.error) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result.message, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Without <code>source</code>, the call applies to all sources. The rollover follows the system time of the ioBroker host; if its time zone is wrong, SourceAnalytix rolls over at the wrong hour.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Yesterday, last week, last month</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Rollover at the wrong time</a></p>`,53)])])}const m=t(d,[["render",l]]);export{f as __pageData,m as default};
